// Generated by AI
#if UNITY_EDITOR
using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

/// <summary>
/// Editor tool that makes the S.U.C.K.-3000 prop look less simple: it generates textures
/// (brushed metal panels with rivets, hazard stripes, ribbed hose), creates textured materials,
/// applies them to the prop and adds details (top cap, vents, gauge, handle, tank rings, glow strips,
/// hose collars and a glowing funnel rim).
/// Select PlayerArmature (or the prop itself) and use Tools > S.U.C.K.-3000 > Add Vacuum Details.
/// It can be run again: it removes its previous details first.
/// This file must be inside a folder named "Editor".
/// </summary>
public static class VacuumPropDetailer
{
    private const string PropName = "SUCK3000_Prop";
    private const string DetailPrefix = "Detail_";
    private const string MaterialFolder = "Assets/GameMaterials";
    private const string TextureFolder = "Assets/GameMaterials/Textures";

    [MenuItem("Tools/S.U.C.K.-3000/Add Vacuum Details")]
    public static void AddDetails()
    {
        Transform prop = FindProp();
        if (prop == null)
        {
            EditorUtility.DisplayDialog(
                "S.U.C.K.-3000",
                "Select PlayerArmature (or SUCK3000_Prop) first. If the prop does not exist yet, run Build Vacuum Prop.",
                "OK");
            return;
        }

        EnsureFolders();

        // Textures are generated in code, so no image files are needed.
        Texture2D panelTexture = MakeTexture("SUCK_Panel", 256, PanelPixel);
        Texture2D stripeTexture = MakeTexture("SUCK_Stripes", 256, StripePixel);
        Texture2D ribTexture = MakeTexture("SUCK_Ribs", 128, RibPixel);

        Material metal = ConfigureMaterial("SUCK_DarkMetal_Tex", new Color(0.42f, 0.45f, 0.5f), panelTexture, new Vector2(1f, 1f), 0.8f, 0.55f);
        Material teal = ConfigureMaterial("SUCK_Teal_Tex", new Color(0.15f, 0.85f, 0.75f), panelTexture, new Vector2(1f, 1f), 0.35f, 0.65f);
        Material hose = ConfigureMaterial("SUCK_Hose_Tex", new Color(0.55f, 0.55f, 0.6f), ribTexture, new Vector2(1f, 8f), 0.2f, 0.4f);
        Material hazard = ConfigureMaterial("SUCK_Hazard_Tex", Color.white, stripeTexture, new Vector2(2f, 1f), 0.1f, 0.4f);
        Material black = ConfigureMaterial("SUCK_Black", new Color(0.04f, 0.04f, 0.05f), null, Vector2.one, 0.5f, 0.5f);
        Material glow = ConfigureGlowMaterial("SUCK_Light", new Color(0.2f, 0.9f, 1f));

        // Remove details from a previous run.
        for (int i = prop.childCount - 1; i >= 0; i--)
        {
            Transform child = prop.GetChild(i);
            if (child.name.StartsWith(DetailPrefix))
            {
                Undo.DestroyObjectImmediate(child.gameObject);
            }
        }

        // Put the textured materials on the parts that already exist.
        Apply(prop, "Backpack_Body", metal);
        Apply(prop, "Tank_Left", teal);
        Apply(prop, "Tank_Right", teal);
        Apply(prop, "Funnel", teal);
        Apply(prop, "Funnel_Inside", black);
        Apply(prop, "Hose_0", hose);
        Apply(prop, "Hose_1", hose);
        Apply(prop, "Hose_2", hose);
        for (int i = 0; i < 4; i++)
        {
            Apply(prop, "Hose_Joint_" + i, metal);
        }

        // ---- Backpack details (positions follow the same layout as Build Vacuum Prop) ----
        AddPart(prop, "TopCap", PrimitiveType.Cube, new Vector3(0f, 1.62f, -0.28f), Quaternion.identity, new Vector3(0.46f, 0.05f, 0.26f), teal);
        AddPart(prop, "BasePlate", PrimitiveType.Cube, new Vector3(0f, 0.99f, -0.28f), Quaternion.identity, new Vector3(0.46f, 0.05f, 0.26f), hazard);
        AddPart(prop, "BackPanel", PrimitiveType.Cube, new Vector3(0f, 1.3f, -0.40f), Quaternion.identity, new Vector3(0.34f, 0.46f, 0.02f), teal);

        for (int i = 0; i < 4; i++)
        {
            AddPart(prop, "Vent_" + i, PrimitiveType.Cube,
                new Vector3(0f, 1.12f + 0.045f * i, -0.412f), Quaternion.identity, new Vector3(0.26f, 0.014f, 0.012f), black);
        }

        Quaternion faceBack = Quaternion.Euler(90f, 0f, 0f);
        AddPart(prop, "GaugeRing", PrimitiveType.Cylinder, new Vector3(0.11f, 1.5f, -0.408f), faceBack, new Vector3(0.11f, 0.01f, 0.11f), black);
        AddPart(prop, "GaugeFace", PrimitiveType.Cylinder, new Vector3(0.11f, 1.5f, -0.416f), faceBack, new Vector3(0.085f, 0.008f, 0.085f), glow);

        // Carry handle on top.
        AddPart(prop, "HandleBar", PrimitiveType.Cube, new Vector3(0f, 1.69f, -0.28f), Quaternion.identity, new Vector3(0.2f, 0.02f, 0.02f), black);
        AddPart(prop, "HandlePostL", PrimitiveType.Cube, new Vector3(-0.09f, 1.66f, -0.28f), Quaternion.identity, new Vector3(0.02f, 0.06f, 0.02f), black);
        AddPart(prop, "HandlePostR", PrimitiveType.Cube, new Vector3(0.09f, 1.66f, -0.28f), Quaternion.identity, new Vector3(0.02f, 0.06f, 0.02f), black);

        // Tank rings, caps and glow strips.
        float[] tankX = { -0.3f, 0.3f };
        for (int t = 0; t < tankX.Length; t++)
        {
            string side = t == 0 ? "L" : "R";
            float x = tankX[t];

            AddPart(prop, "TankRingTop_" + side, PrimitiveType.Cylinder, new Vector3(x, 1.4f, -0.28f), Quaternion.identity, new Vector3(0.18f, 0.012f, 0.18f), black);
            AddPart(prop, "TankRingBottom_" + side, PrimitiveType.Cylinder, new Vector3(x, 1.1f, -0.28f), Quaternion.identity, new Vector3(0.18f, 0.012f, 0.18f), black);
            AddPart(prop, "TankCapTop_" + side, PrimitiveType.Sphere, new Vector3(x, 1.55f, -0.28f), Quaternion.identity, new Vector3(0.16f, 0.1f, 0.16f), teal);
            AddPart(prop, "TankCapBottom_" + side, PrimitiveType.Sphere, new Vector3(x, 0.95f, -0.28f), Quaternion.identity, new Vector3(0.16f, 0.1f, 0.16f), teal);
            AddPart(prop, "TankGlow_" + side, PrimitiveType.Cube, new Vector3(x, 1.25f, -0.197f), Quaternion.identity, new Vector3(0.014f, 0.34f, 0.014f), glow);
        }

        // Hose collars at both ends.
        Vector3 hoseStart = new Vector3(0.22f, 1.45f, -0.3f);
        Vector3 hoseSecond = new Vector3(0.38f, 1.6f, -0.05f);
        Vector3 hoseEnd = new Vector3(0.3f, 1.0f, 0.6f);
        Vector3 hoseBeforeEnd = new Vector3(0.4f, 1.15f, 0.35f);

        Vector3 startDir = (hoseSecond - hoseStart).normalized;
        AddTube(prop, "CollarStart", hoseStart, hoseStart + startDir * 0.08f, 0.06f, teal);

        Vector3 endDir = (hoseEnd - hoseBeforeEnd).normalized;
        AddTube(prop, "CollarEnd", hoseEnd - endDir * 0.14f, hoseEnd, 0.065f, teal);

        // Glowing rim around the funnel mouth.
        Quaternion pointForward = Quaternion.Euler(90f, 0f, 0f);
        AddPart(prop, "FunnelRim", PrimitiveType.Cylinder, new Vector3(0.3f, 1.0f, 0.797f), pointForward, new Vector3(0.36f, 0.012f, 0.36f), glow);

        EditorSceneManager.MarkSceneDirty(prop.gameObject.scene);
        Debug.Log("S.U.C.K.-3000 prop details added. Save the scene with Ctrl + S.");
    }

    // ---------- Finding the prop ----------

    private static Transform FindProp()
    {
        GameObject selected = Selection.activeGameObject;
        if (selected == null) return null;

        // The prop itself, or one of its parts, is selected.
        Transform walker = selected.transform;
        while (walker != null)
        {
            if (walker.name == PropName) return walker;
            walker = walker.parent;
        }

        // PlayerArmature (or anything below it) is selected: search below the object with the absorber.
        VacuumAbsorber absorber = selected.GetComponentInParent<VacuumAbsorber>();
        Transform searchRoot = absorber != null ? absorber.transform : selected.transform;
        foreach (Transform candidate in searchRoot.GetComponentsInChildren<Transform>(true))
        {
            if (candidate.name == PropName) return candidate;
        }

        return null;
    }

    // ---------- Parts ----------

    private static void Apply(Transform prop, string partName, Material material)
    {
        Transform part = FindDeep(prop, partName);
        if (part == null) return;

        MeshRenderer renderer = part.GetComponent<MeshRenderer>();
        if (renderer == null) return;

        Undo.RecordObject(renderer, "Apply prop material");
        renderer.sharedMaterial = material;
    }

    private static Transform FindDeep(Transform root, string partName)
    {
        foreach (Transform candidate in root.GetComponentsInChildren<Transform>(true))
        {
            if (candidate.name == partName) return candidate;
        }

        return null;
    }

    private static void AddPart(
        Transform prop, string partName, PrimitiveType type,
        Vector3 localPosition, Quaternion localRotation, Vector3 localScale, Material material)
    {
        GameObject part = GameObject.CreatePrimitive(type);
        part.name = DetailPrefix + partName;

        // Decorative only: no collider, so it never pushes the player or blocks anything.
        Object.DestroyImmediate(part.GetComponent<Collider>());

        Undo.RegisterCreatedObjectUndo(part, "Add vacuum detail");
        part.transform.SetParent(prop, false);
        part.transform.localPosition = localPosition;
        part.transform.localRotation = localRotation;
        part.transform.localScale = localScale;
        part.GetComponent<MeshRenderer>().sharedMaterial = material;
    }

    private static void AddTube(Transform prop, string tubeName, Vector3 from, Vector3 to, float radius, Material material)
    {
        Vector3 direction = to - from;

        // A Unity cylinder is 2 units tall and 1 unit wide, so the scale is half the length.
        AddPart(prop, tubeName, PrimitiveType.Cylinder,
            (from + to) / 2f,
            Quaternion.FromToRotation(Vector3.up, direction.normalized),
            new Vector3(radius * 2f, direction.magnitude / 2f, radius * 2f),
            material);
    }

    // ---------- Materials ----------

    private static Material ConfigureMaterial(
        string materialName, Color color, Texture2D texture, Vector2 tiling, float metallic, float smoothness)
    {
        string path = MaterialFolder + "/" + materialName + ".mat";
        Material material = AssetDatabase.LoadAssetAtPath<Material>(path);
        if (material == null)
        {
            Shader shader = Shader.Find("Universal Render Pipeline/Lit");
            if (shader == null) shader = Shader.Find("Standard");
            material = new Material(shader);
            AssetDatabase.CreateAsset(material, path);
        }

        if (material.HasProperty("_BaseColor")) material.SetColor("_BaseColor", color);
        if (material.HasProperty("_Color")) material.SetColor("_Color", color);
        if (material.HasProperty("_Metallic")) material.SetFloat("_Metallic", metallic);
        if (material.HasProperty("_Smoothness")) material.SetFloat("_Smoothness", smoothness);
        if (material.HasProperty("_Glossiness")) material.SetFloat("_Glossiness", smoothness);

        if (texture != null)
        {
            if (material.HasProperty("_BaseMap"))
            {
                material.SetTexture("_BaseMap", texture);
                material.SetTextureScale("_BaseMap", tiling);
            }

            if (material.HasProperty("_MainTex"))
            {
                material.SetTexture("_MainTex", texture);
                material.SetTextureScale("_MainTex", tiling);
            }
        }

        EditorUtility.SetDirty(material);
        return material;
    }

    private static Material ConfigureGlowMaterial(string materialName, Color color)
    {
        Material material = ConfigureMaterial(materialName, color, null, Vector2.one, 0f, 0.5f);
        material.EnableKeyword("_EMISSION");
        material.SetColor("_EmissionColor", color * 3f);
        EditorUtility.SetDirty(material);
        return material;
    }

    // ---------- Procedural textures ----------

    private static Texture2D MakeTexture(string textureName, int size, System.Func<int, int, Color> pixel)
    {
        string path = TextureFolder + "/" + textureName + ".png";

        Texture2D texture = new Texture2D(size, size, TextureFormat.RGBA32, false);
        for (int y = 0; y < size; y++)
        {
            for (int x = 0; x < size; x++)
            {
                texture.SetPixel(x, y, pixel(x, y));
            }
        }

        texture.Apply();
        File.WriteAllBytes(path, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);

        AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);
        return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
    }

    // Brushed metal with panel lines and rivets (grey, tinted by the material color).
    private static Color PanelPixel(int x, int y)
    {
        float brushed = Mathf.PerlinNoise(x * 0.03f, y * 0.8f);
        float value = 0.62f + (brushed - 0.5f) * 0.25f;

        int cellX = x % 64;
        int cellY = y % 64;

        if (cellX < 2 || cellY < 2)
        {
            value *= 0.55f;
        }

        if (IsRivet(cellX, cellY, 10, 10) || IsRivet(cellX, cellY, 54, 10) ||
            IsRivet(cellX, cellY, 10, 54) || IsRivet(cellX, cellY, 54, 54))
        {
            value = 0.95f;
        }

        return new Color(value, value, value, 1f);
    }

    private static bool IsRivet(int x, int y, int centerX, int centerY)
    {
        int dx = x - centerX;
        int dy = y - centerY;
        return dx * dx + dy * dy < 7;
    }

    // Yellow and black diagonal hazard stripes.
    private static Color StripePixel(int x, int y)
    {
        bool yellow = ((x + y) / 24) % 2 == 0;
        return yellow ? new Color(1f, 0.8f, 0.1f, 1f) : new Color(0.08f, 0.08f, 0.08f, 1f);
    }

    // Horizontal ribs, used for the hose.
    private static Color RibPixel(int x, int y)
    {
        float band = Mathf.Sin(y * Mathf.PI * 2f / 16f) * 0.5f + 0.5f;
        float value = 0.25f + 0.55f * band;
        return new Color(value, value, value, 1f);
    }

    // ---------- Folders ----------

    private static void EnsureFolders()
    {
        if (!AssetDatabase.IsValidFolder(MaterialFolder))
        {
            AssetDatabase.CreateFolder("Assets", "GameMaterials");
        }

        if (!AssetDatabase.IsValidFolder(TextureFolder))
        {
            AssetDatabase.CreateFolder(MaterialFolder, "Textures");
        }
    }
}
#endif
